/*
 * High-performance portfolio calculations using C extension
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array = NULL, *cov_array = NULL;

    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                          &PyArray_Type, &cov_array))
        return NULL;

    npy_intp n = PyArray_DIM(weights_array, 0);

    double *weights = (double*)PyArray_DATA(weights_array);
    double *cov = (double*)PyArray_DATA(cov_array);

    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; i++) {
        double row_sum = 0.0;
        double wi = weights[i];
        double *row = cov + i * n;
        for (npy_intp j = 0; j < n; j++) {
            row_sum += row[j] * weights[j];
        }
        risk_squared += wi * row_sum;
    }

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array = NULL, *returns_array = NULL;

    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                          &PyArray_Type, &returns_array))
        return NULL;

    npy_intp n = PyArray_DIM(weights_array, 0);

    double *weights = (double*)PyArray_DATA(weights_array);
    double *returns = (double*)PyArray_DATA(returns_array);

    double total = 0.0;
    for (npy_intp i = 0; i < n; i++) {
        total += weights[i] * returns[i];
    }

    return PyFloat_FromDouble(total);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();
    return PyModule_Create(&moduledef);
}

/*
 * High-performance portfolio calculations using C extension.
 * Accepts Python lists directly to avoid NumPy conversion overhead.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static double extract_double(PyObject *obj) {
    if (PyFloat_CheckExact(obj)) {
        return PyFloat_AS_DOUBLE(obj);
    }
    double v = PyFloat_AsDouble(obj);
    if (v == -1.0 && PyErr_Occurred()) {
        PyErr_Clear();
    }
    return v;
}

static int parse_double_array(PyObject *list_obj, double **out_data, Py_ssize_t *out_n) {
    if (!PyList_Check(list_obj)) {
        PyErr_SetString(PyExc_TypeError, "expected a Python list");
        return -1;
    }
    Py_ssize_t n = PyList_GET_SIZE(list_obj);
    double *data = (double*)malloc((size_t)n * sizeof(double));
    if (!data) {
        PyErr_NoMemory();
        return -1;
    }
    for (Py_ssize_t i = 0; i < n; i++) {
        data[i] = extract_double(PyList_GET_ITEM(list_obj, i));
    }
    *out_data = data;
    *out_n = n;
    return 0;
}

static int parse_double_matrix(PyObject *list_obj, double **out_data, Py_ssize_t *out_n) {
    if (!PyList_Check(list_obj)) {
        PyErr_SetString(PyExc_TypeError, "expected a Python list of lists");
        return -1;
    }
    Py_ssize_t n = PyList_GET_SIZE(list_obj);
    double *data = (double*)malloc((size_t)n * (size_t)n * sizeof(double));
    if (!data) {
        PyErr_NoMemory();
        return -1;
    }
    for (Py_ssize_t i = 0; i < n; i++) {
        PyObject *row = PyList_GET_ITEM(list_obj, i);
        if (!PyList_Check(row)) {
            PyErr_SetString(PyExc_TypeError, "covariance matrix rows must be lists");
            free(data);
            return -1;
        }
        if (PyList_GET_SIZE(row) != n) {
            PyErr_SetString(PyExc_ValueError, "covariance matrix must be square");
            free(data);
            return -1;
        }
        for (Py_ssize_t j = 0; j < n; j++) {
            data[i * n + j] = extract_double(PyList_GET_ITEM(row, j));
        }
    }
    *out_data = data;
    *out_n = n;
    return 0;
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;
    double *weights = NULL, *cov = NULL;
    Py_ssize_t n = 0;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    if (parse_double_array(weights_obj, &weights, &n) < 0)
        return NULL;

    Py_ssize_t n_cov;
    if (parse_double_matrix(cov_obj, &cov, &n_cov) < 0) {
        free(weights);
        return NULL;
    }
    if (n_cov != n) {
        free(weights);
        free(cov);
        PyErr_SetString(PyExc_ValueError, "weights length must match covariance dimension");
        return NULL;
    }

    double risk_squared = 0.0;
    for (Py_ssize_t i = 0; i < n; i++) {
        double wi = weights[i];
        double *row = cov + i * n;
        double row_sum = 0.0;
        for (Py_ssize_t j = 0; j < n; j++) {
            row_sum += row[j] * weights[j];
        }
        risk_squared += wi * row_sum;
    }

    free(weights);
    free(cov);
    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;
    double *weights = NULL, *returns = NULL;
    Py_ssize_t n = 0;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    if (parse_double_array(weights_obj, &weights, &n) < 0)
        return NULL;

    Py_ssize_t n_r;
    if (parse_double_array(returns_obj, &returns, &n_r) < 0) {
        free(weights);
        return NULL;
    }
    if (n_r != n) {
        free(weights);
        free(returns);
        PyErr_SetString(PyExc_ValueError, "weights and returns must have the same length");
        return NULL;
    }

    double total = 0.0;
    for (Py_ssize_t i = 0; i < n; i++) {
        total += weights[i] * returns[i];
    }

    free(weights);
    free(returns);
    return PyFloat_FromDouble(total);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
